PRAGMA foreign_keys=ON;
CREATE TABLE shipping_providers(code TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,production_ready INTEGER NOT NULL DEFAULT 0,provider_status TEXT NOT NULL DEFAULT 'disabled');
CREATE TABLE merchant_shipping_integrations(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,provider TEXT NOT NULL REFERENCES shipping_providers(code),enabled INTEGER NOT NULL DEFAULT 0,production_ready INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'disabled',encrypted_config TEXT,UNIQUE(merchant_id,provider));
CREATE TABLE shipping_methods(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,provider TEXT NOT NULL,method_type TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,cod_enabled INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE shipping_rate_rules(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,method_id TEXT NOT NULL REFERENCES shipping_methods(id),min_amount_minor INTEGER,min_weight_grams INTEGER,regions_json TEXT NOT NULL DEFAULT '[]',rate_minor INTEGER NOT NULL CHECK(rate_minor>=0));
CREATE TABLE commerce_shipments(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',tracking_no TEXT,label_object_key TEXT,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key),FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_shipment_items(shipment_id TEXT NOT NULL REFERENCES commerce_shipments(id),order_item_id TEXT NOT NULL REFERENCES commerce_order_items(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(shipment_id,order_item_id));
CREATE TABLE commerce_tracking_events(id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES commerce_shipments(id),provider_event_id TEXT,status TEXT NOT NULL,occurred_at TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',UNIQUE(shipment_id,provider_event_id));
CREATE TABLE commerce_payment_intents(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'created',amount_minor INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'TWD',provider_reference TEXT,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key),FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_payment_events(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,provider TEXT NOT NULL,provider_event_id TEXT NOT NULL,event_type TEXT NOT NULL,intent_id TEXT,verified INTEGER NOT NULL DEFAULT 0,processed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_event_id));
CREATE TABLE merchant_invoice_integrations(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,provider TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,production_ready INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'disabled',encrypted_config TEXT,UNIQUE(merchant_id,provider));
CREATE TABLE commerce_invoices(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,provider TEXT NOT NULL,invoice_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',invoice_no TEXT,buyer_tax_id TEXT,carrier_type TEXT,carrier_value_encrypted TEXT,donation_code TEXT,provider_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_invoice_events(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES commerce_invoices(id),event_type TEXT NOT NULL,provider_event_id TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(invoice_id,provider_event_id));
